chrome.runtime.onInstalled.addListener(function () {
    // Save metrics back to storage
    chrome.storage.local.get({ settings: new Settings() }, (result) => {
        let set = result.settings;
        // If settings were just created (default), or if we need to update version/name
        // We want to preserve clientId and apiKey if they exist in the retrieved settings
        // But since we used default value in .get(), 'set' might be a fresh object if nothing was in storage.
        // Actually, chrome.storage.local.get with default will return the default if key is missing.
        // If key exists, it returns what's in storage.
        // So 'set' is either the existing settings or a new default one.
        // We should update the version and name in case of update
        set.ext_version = chrome.runtime.getManifest().version;
        set.ext_name = chrome.runtime.getManifest().name;
        // If it was a fresh default, clientId is already set by constructor.
        // If it was existing, clientId is preserved.
        chrome.storage.local.set({ settings: set }, () => {
            if (chrome.runtime.lastError) {
                log.error('Error saving metrics:', chrome.runtime.lastError);
                return;
            }
            log.debug('Metrics stored. ');
            triggerInstalledEvent();
        });
    });
});
