function extractModelInfos(url, body) {
    let infos = new ModelInfos();
    if (url.startsWith('https://chat.ecollm.fr/')) {
        // infos.provider = "ecollm"; // TODO -> update otherwise we endup with undefined
        const model = JSON.parse(body)['model'];
        var model_provider;
        if (model.includes('gpt')) {
            model_provider = "openai";
        }
        else if (model.includes('mistral')) {
            model_provider = "mistralai";
        }
        const modelData = EcoLogitsData.instance.findModel(model_provider, model);
        infos.model = model;
        log.debug("model found is " + modelData.name);
        log.debug("model found active params ", modelData.activeParameters);
        log.debug("model found total params ", modelData.totalParameters);
        infos.activeparametercount = EcoLogitsData.calculateAverage(modelData.activeParameters);
        infos.totalparametercount = EcoLogitsData.calculateAverage(modelData.totalParameters);
        // infos.tokenizer = modelData.name;
    }
    else if (url.startsWith("https://chatgpt.com/") || url.startsWith("https://copilot.microsoft.com/")) {
        infos.model_provider = "openai";
        const model = JSON.parse(body)['model'];
        log.debug("model found is " + model);
        const modelData = EcoLogitsData.instance.findModel("openai", model);
        infos.model = model;
        infos.activeparametercount = EcoLogitsData.calculateAverage(modelData.activeParameters);
        infos.totalparametercount = EcoLogitsData.calculateAverage(modelData.totalParameters);
        // infos.tokenizer = modelData.name;
    }
    else if (url.startsWith("https://chat.mistral.ai/")) {
        infos.model_provider = "mistralai";
        const model = JSON.parse(body)['model'];
        const modelData = EcoLogitsData.instance.findModel("mistralai", model);
        infos.model = model;
        log.debug("model found is " + modelData);
        infos.activeparametercount = EcoLogitsData.calculateAverage(modelData.activeParameters);
        infos.totalparametercount = EcoLogitsData.calculateAverage(modelData.totalParameters);
        // infos.tokenizer = model;
    }
    else {
        infos.model_provider = "unknown";
        log.debug("Error, didn't find the model for: " + body);
        throw new Error("Error, didn't find the model for: " + body);
    }
    return infos;
}
function SaveEvent(chatevent) {
    chrome.storage.local.get({ aggregates: {}, chatEvents: [], settings: new Settings() }, (result) => {
        if (chrome.runtime.lastError) {
            log.error('Error retrieving metrics:', chrome.runtime.lastError);
            return;
        }
        var aggregates = result.aggregates;
        var chatEvents = result.chatEvents;
        var settings = result.settings;
        // Add to existing entry or create a new one
        const sitemodel = chatevent.inference_provider; // + "-" + chatevent.model;
        if (aggregates[sitemodel]) {
            aggregates[sitemodel].nb_requests += 1;
            aggregates[sitemodel].energy_value += chatevent.energy_value;
            aggregates[sitemodel].gwp_value += chatevent.gwp_value;
            aggregates[sitemodel].nb_tokens += chatevent.nb_tokens;
            aggregates[sitemodel].latency += chatevent.latency;
        }
        else {
            aggregates[sitemodel] = {
                nb_requests: 1,
                energy_value: chatevent.energy_value,
                energy_unit: chatevent.energy_unit,
                gwp_value: chatevent.gwp_value,
                gwp_unit: chatevent.gwp_unit,
                nb_tokens: chatevent.nb_tokens,
                latency: chatevent.latency,
                model: chatevent.model,
            };
        }
        log.debug("arranging an overall aggregate for display.");
        // increment general counter
        if (aggregates["all"]) {
            log.debug("creating aggregate for \"all\"");
            aggregates["all"].nb_requests += 1;
            aggregates["all"].energy_value += chatevent.energy_value;
            aggregates["all"].gwp_value += chatevent.gwp_value;
            aggregates["all"].nb_tokens += chatevent.nb_tokens;
            aggregates["all"].latency += chatevent.latency;
        }
        else {
            log.debug("updaging aggregate for \"all\"");
            aggregates["all"] = {
                nb_requests: 1,
                energy_value: chatevent.energy_value,
                energy_unit: chatevent.energy_unit,
                gwp_value: chatevent.gwp_value,
                gwp_unit: chatevent.gwp_unit,
                nb_tokens: chatevent.nb_tokens,
                latency: chatevent.latency,
                model: "all",
            };
        }
        chatEvents.push(chatevent);
        // Save metrics back to storage
        // IMPORTANT: We must also save 'settings' back, because if it was missing and we used the default
        // from .get(), we want to persist that default (which has a new clientId) so it stays consistent.
        chrome.storage.local.set({ aggregates: aggregates, chatEvents: chatEvents, settings: settings }, () => {
            if (chrome.runtime.lastError) {
                log.error('Error saving metrics:', chrome.runtime.lastError);
                return;
            }
            log.debug('Metrics stored.');
        });
        sendEvent("ecollm_extension_inference_processed", { model: chatevent.model });
        // Push event to backend if apiKey is configured
        if (settings && settings.apiKey) {
            const backendUrl = settings.backendUrl || "http://localhost:3000";
            log.debug("Pushing event to backend: " + backendUrl);
            fetch(`${backendUrl.replace(/\/$/, '')}/api/extension/event`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'x-api-key': settings.apiKey
                },
                body: JSON.stringify({
                    clientId: settings.clientId,
                    event: chatevent
                })
            })
                .then(async (response) => {
                if (!response.ok) {
                    const text = await response.text();
                    log.error('Failed to push event to backend:', response.statusText, text);
                }
                else {
                    log.debug('Event pushed to backend successfully');
                }
            })
                .catch(error => {
                log.error('Error pushing event to backend:', error);
            });
        }
    });
}
class ChatEvent {
    constructor(properties) {
        let modelinfos = extractModelInfos(properties.url, properties.body);
        this.nb_tokens = 0;
        this.starttime = properties.starttime;
        const model = JSON.parse(properties.body)['model'];
        if (properties.url.includes('ecollm')) {
            this.inference_provider = 'ecollm';
            if (model.includes('gpt')) {
                this.model_provider = 'openai';
            }
            else if (model.includes('mistral')) {
                this.model_provider = 'mistralai';
            }
            else {
                throw new Error("Model provider not recognised!");
            }
        }
        else if (properties.url.includes('mistral')) {
            this.inference_provider = 'mistral';
            this.model_provider = 'mistralai';
        }
        else if (properties.url.includes('copilot')) {
            this.inference_provider = 'copilot';
            this.model_provider = 'openai';
        }
        else {
            this.inference_provider = 'openai';
            this.model_provider = 'openai';
        }
        this.model = modelinfos.model;
        this.latency = properties.latency;
        if (this.model_provider === "mistralai") {
            this.nb_tokens = mistralTokenizer.encode(properties.generated_text).length;
        }
        else {
            this.nb_tokens = countTokens(properties.generated_text);
        }
        const impacts = computeLlmImpacts(modelinfos.activeparametercount, modelinfos.totalparametercount, this.nb_tokens, this.latency);
        this.energy_value = impacts.energy.value;
        this.energy_unit = impacts.energy.unit;
        this.gwp_value = impacts.gwp.value;
        this.gwp_unit = impacts.gwp.unit;
        this.discussion_url = properties.url;
        this.model_nb_parameters = '' + modelinfos.activeparametercount;
    }
}
