// https://developer.chrome.com/docs/extensions/develop/migrate/to-service-workers
/**
 * Tracks when a service worker was last alive and extends the service worker
 * lifetime by writing the current time to extension storage every 20 seconds.
 * You should still prepare for unexpected termination - for example, if the
 * extension process crashes or your extension is manually stopped at
 * chrome://serviceworker-internals.
 */
let heartbeatInterval;
async function runHeartbeat() {
    log.debug('run heartbeat.');
    heartbeatToGA();
    const lastHeartbeat = new Date().getTime();
    await chrome.storage.local.set({ 'last-heartbeat': lastHeartbeat });
    // Sync heartbeat to backend if apiKey is configured
    chrome.storage.local.get({ settings: new Settings() }, (result) => {
        const settings = result.settings;
        // Ensure we save the settings back if we used the default, to persist the clientId
        chrome.storage.local.set({ settings: settings });
        if (settings && settings.apiKey) {
            const backendUrl = settings.backendUrl || "http://localhost:3000";
            log.debug("Syncing heartbeat to backend: " + backendUrl);
            fetch(`${backendUrl.replace(/\/$/, '')}/api/extension/sync`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'x-api-key': settings.apiKey
                },
                body: JSON.stringify({
                    clientId: settings.clientId,
                    lastHeartbeat: lastHeartbeat,
                    settings: {
                        ext_name: settings.ext_name,
                        ext_version: settings.ext_version,
                        installationTime: settings.installationTime
                    }
                })
            })
                .then(async (response) => {
                if (!response.ok) {
                    const text = await response.text();
                    log.error('Failed to sync heartbeat to backend:', response.statusText, text);
                    chrome.storage.local.set({ connectionStatus: 'disconnected' });
                }
                else {
                    log.debug('Heartbeat synced to backend successfully');
                    chrome.storage.local.set({ connectionStatus: 'connected' });
                }
            })
                .catch(error => {
                log.error('Error syncing heartbeat to backend:', error);
                chrome.storage.local.set({ connectionStatus: 'disconnected' });
            });
        }
    });
}
/**
 * Starts the heartbeat interval which keeps the service worker alive. Call
 * this sparingly when you are doing work which requires persistence, and call
 * stopHeartbeat once that work is complete.
 */
async function startHeartbeat() {
    // Run the heartbeat once at service worker startup.
    runHeartbeat().then(() => {
        // Then again every 20 seconds.
        log.debug('start heartbeat.');
        heartbeatInterval = setInterval(runHeartbeat, 20 * 1000);
    });
}
async function stopHeartbeat() {
    clearInterval(heartbeatInterval);
}
/**
 * Returns the last heartbeat stored in extension storage, or undefined if
 * the heartbeat has never run before.
 */
async function getLastHeartbeat() {
    return (await chrome.storage.local.get('last-heartbeat'))['last-heartbeat'];
}
