export class ModelInfos {
    constructor(overrides) {
        if (overrides) {
            Object.assign(this, overrides);
        }
    }
}
export class Settings {
    constructor() {
        this.installationTime = Date.now();
        this.ext_version = chrome.runtime.getManifest().version;
        this.ext_name = chrome.runtime.getManifest().name;
        this.clientId = self.crypto.randomUUID();
        this.backendUrl = "http://localhost:3000";
        // Commit injected at build time (DefinePlugin)
        this.commit = typeof __COMMIT__ === "string" ? __COMMIT__ : "";
        // console.log("version retrived: " + this.ext_name + ", " + this.ext_version);
    }
}
